import { supabase } from "@/lib/supabaseClient";

// One row per pending "present + auto-queue" request. A unique constraint
// on player_id means re-requesting just refreshes the existing row instead
// of creating a duplicate.

export async function createPresenceRequest(playerId, playerName) {
  const { error } = await supabase
    .from("player_requests")
    .upsert(
      { player_id: playerId, player_name: playerName, created_at: new Date().toISOString() },
      { onConflict: "player_id" }
    );

  if (error) throw new Error(error.message);
}

export async function cancelPresenceRequest(playerId) {
  const { error } = await supabase
    .from("player_requests")
    .delete()
    .eq("player_id", playerId);

  if (error) throw new Error(error.message);
}

// Resolves (approves or denies) a request by deleting its row.
export async function resolvePresenceRequest(requestId) {
  const { error } = await supabase
    .from("player_requests")
    .delete()
    .eq("id", requestId);

  if (error) throw new Error(error.message);
}

// Admin-only: every pending request, oldest first.
export async function getAllPresenceRequests() {
  const { data, error } = await supabase
    .from("player_requests")
    .select("*")
    .order("created_at", { ascending: true });

  if (error) throw new Error(error.message);
  return data;
}

// Player-only: just this player's own pending request, if any.
export async function getOwnPresenceRequest(playerId) {
  const { data, error } = await supabase
    .from("player_requests")
    .select("*")
    .eq("player_id", playerId)
    .maybeSingle();

  if (error) throw new Error(error.message);
  return data;
}

// Admin-only: live updates across the whole requests table.
export function subscribeToAllPresenceRequests(onChange) {
  const channel = supabase
    .channel("player_requests_admin")
    .on(
      "postgres_changes",
      { event: "*", schema: "public", table: "player_requests" },
      onChange
    )
    .subscribe();

  return () => supabase.removeChannel(channel);
}

// Player-only: live updates filtered server-side to just this player's row,
// so a player's client never receives other players' request data.
export function subscribeToOwnPresenceRequest(playerId, onChange) {
  const channel = supabase
    .channel(`player_requests_own_${playerId}`)
    .on(
      "postgres_changes",
      {
        event: "*",
        schema: "public",
        table: "player_requests",
        filter: `player_id=eq.${playerId}`,
      },
      onChange
    )
    .subscribe();

  return () => supabase.removeChannel(channel);
}